/**
 * Unit tests for AbstractIntegrator.acceptStep.
 * Since acceptStep is protected, we use a Test subclass to expose it.
 */
public class AbstractIntegrator_acceptStep_TriageGen1Test {

    private TestIntegrator integrator;
    private AbstractStepInterpolator interpolator;
    private double[] y;
    private double[] yDot;
    private double tEnd;

    // Concrete implementation to test protected methods
    private static class TestIntegrator extends AbstractIntegrator {
        private boolean statesInitialized = false;
        private boolean resetOccurred = false;
        private boolean isLastStep = false;
        private List<EventState> eventsStates = new ArrayList<>();
        private List<StepHandler> stepHandlers = new ArrayList<>();
        private FirstOrderDifferentialEquations equations;

        protected TestIntegrator() {
            super("TestIntegrator");
        }

        @Override
        public void integrate(FirstOrderDifferentialEquations equations, double t0, double[] y0, double t, double[] y) {
            this.equations = equations;
        }

        @Override
        public void integrate(ExpandableStatefulODE equations, double t) {
            this.equations = (FirstOrderDifferentialEquations) equations;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            // Mock behavior for derivative computation
        }

        @Override
        protected void setStateInitialized(boolean stateInitialized) {
            this.statesInitialized = stateInitialized;
        }

        // Expose protected method for testing
        @Override
        protected double acceptStep(AbstractStepInterpolator interpolator, double[] y, double[] yDot, double tEnd) 
                throws MathIllegalStateException {
            return super.acceptStep(interpolator, y, yDot, tEnd);
        }

        // Accessors for internal state tracking
        public boolean isStatesInitialized() { return statesInitialized; }
        public boolean isResetOccurred() { return resetOccurred; }
        public boolean isLastStep() { return isLastStep; }
        public void setStatesInitialized(boolean val) { this.statesInitialized = val; }
        public void setEventsStates(List<EventState> states) { this.eventsStates = states; }
        public void setStepHandlers(List<StepHandler> handlers) { this.stepHandlers = handlers; }
        public void setLastStep(boolean lastStep) { this.isLastStep = lastStep; }
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        interpolator = mock(AbstractStepInterpolator.class);
        y = new double[]{1.0, 2.0};
        yDot = new double[]{0.0, 0.0};
        tEnd = 1.0;

        when(interpolator.isForward()).thenReturn(true);
    }

    @Test
    public void testAcceptStep_NoEventsOccur() {
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        EventState mockEvent = mock(EventState.class);
        when(mockEvent.evaluateStep(interpolator)).thenReturn(false);
        integrator.setEventsStates(List.of(mockEvent));

        double result = integrator.acceptStep(interpolator, y, yDot, tEnd);

        assertEquals(1.0, result, 1e-10);
        verify(mockEvent).stepAccepted(eq(1.0), any(double[].class));
        verify(interpolator).setInterpolatedTime(1.0);
    }

    @Test
    public void testAcceptStep_EventTriggersStop() {
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        EventState mockEvent = mock(EventState.class);
        when(mockEvent.evaluateStep(interpolator)).thenReturn(true);
        when(mockEvent.getEventTime()).thenReturn(0.5);
        when(mockEvent.stop()).thenReturn(true); // Triggers isLastStep

        integrator.setEventsStates(List.of(mockEvent));

        double result = integrator.acceptStep(interpolator, y, yDot, tEnd);

        assertEquals(0.5, result, 1e-10);
        assertEquals(1.5, y[0], 1e-10);
        assertTrue(integrator.isLastStep());
    }

    @Test
    public void testAcceptStep_EventTriggersReset() {
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        EventState mockEvent = mock(EventState.class);
        when(mockEvent.evaluateStep(interpolator)).thenReturn(true);
        when(mockEvent.getEventTime()).thenReturn(0.5);
        when(mockEvent.stop()).thenReturn(false);
        when(mockEvent.reset(eq(0.5), any(double[].class))).thenReturn(true);

        integrator.setEventsStates(List.of(mockEvent));

        double result = integrator.acceptStep(interpolator, y, yDot, tEnd);

        assertEquals(0.5, result, 1e-10);
        assertTrue(integrator.isResetOccurred());
        assertEquals(1.5, y[0], 1e-10);
    }

    @Test
    public void testAcceptStep_MultipleEventsChronologicalOrder() {
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.1, 2.1});

        EventState event1 = mock(EventState.class);
        when(event1.getEventTime()).thenReturn(0.4);
        when(event1.evaluateStep(interpolator)).thenReturn(true);
        when(event1.stop()).thenReturn(false);
        when(event1.reset(anyDouble(), any())).thenReturn(false);
        // After event1, event1 checks if it occurs again
        when(event1.evaluateStep(interpolator)).thenReturn(false); 

        EventState event2 = mock(EventState.class);
        when(event2.getEventTime()).thenReturn(0.2); // Should be processed first
        when(event2.evaluateStep(interpolator)).thenReturn(true);
        when(event2.stop()).thenReturn(false);
        when(event2.reset(anyDouble(), any())).thenReturn(false);
        when(event2.evaluateStep(interpolator)).thenReturn(false);

        integrator.setEventsStates(List.of(event1, event2));

        integrator.acceptStep(interpolator, y, yDot, tEnd);

        // Verify event2 (time 0.2) was handled before event1 (time 0.4)
        // We check the interpolation time set by the interpolator
        verify(interpolator).setSoftCurrentTime(0.2); 
    }

    @Test
    public void testAcceptStep_Initialization() {
        integrator.setStatesInitialized(false);
        EventState mockEvent = mock(EventState.class);
        integrator.setEventsStates(List.of(mockEvent));

        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 2.0});

        integrator.acceptStep(interpolator, y, yDot, tEnd);

        verify(mockEvent).reinitializeBegin(interpolator);
        assertTrue(integrator.isStatesInitialized());
    }

    @Test
    public void testAcceptStep_BackwardIntegration() {
        when(interpolator.isForward()).thenReturn(false);
        when(interpolator.getGlobalPreviousTime()).thenReturn(1.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(0.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 1.5});

        EventState mockEvent = mock(EventState.class);
        when(mockEvent.getEventTime()).thenReturn(0.5);
        when(mockEvent.evaluateStep(interpolator)).thenReturn(true);
        when(mockEvent.stop()).thenReturn(false);
        when(mockEvent.reset(anyDouble(), any())).thenReturn(false);
        when(mockEvent.evaluateStep(interpolator)).thenReturn(false);

        integrator.setEventsStates(List.of(mockEvent));

        double result = integrator.acceptStep(interpolator, y, yDot, tEnd);

        assertEquals(0.5, result, 1e-10);
    }

    @Test
    public void testAcceptStep_StepHandlers() {
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 2.0});

        StepHandler handler = mock(StepHandler.class);
        integrator.setStepHandlers(new ArrayList<>(List.of(handler)));

        integrator.acceptStep(interpolator, y, yDot, tEnd);

        verify(handler, atLeastOnce()).handleStep(eq(interpolator), anyBoolean());
    }

    @Test
    public void testAcceptStep_PrecisionEqualsTEnd() {
        double preciseT = 1.0000000000001;
        when(interpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(interpolator.getGlobalCurrentTime()).thenReturn(preciseT);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 2.0});

        integrator.acceptStep(interpolator, y, yDot, 1.0);

        // isLastStep = isLastStep || Precision.equals(currentT, tEnd, 1);
        // This is verified indirectly via the flow if we were to check isLastStep
        // In the code, it sets isLastStep based on tEnd
    }
}
